"use client";
import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import {
  ControlRoll,
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MultiStepFormField {
  name: string;
  label: string;
  type?: "text" | "email" | "tel" | "url" | "number" | "textarea" | "select";
  required?: boolean;
  autoComplete?: string;
  options?: readonly { value: string; label: string }[];
  minLength?: number;
}
export interface MultiStepFormContext {
  values: Record<string, string>;
  setValue: (name: string, value: string) => void;
  submitting: boolean;
}
export interface MultiStepFormStep {
  id: string;
  title: string;
  fields?: readonly MultiStepFormField[];
  render?: (context: MultiStepFormContext) => ReactNode;
  validate?: (values: Record<string, string>) => string | undefined;
}
export interface MultiStepFormProps extends ControlAppearance {
  steps: readonly MultiStepFormStep[];
  value?: Record<string, string>;
  defaultValue?: Record<string, string>;
  onValueChange?: (values: Record<string, string>) => void;
  step?: number;
  defaultStep?: number;
  onStepChange?: (step: number) => void;
  onSubmit?: (
    values: Record<string, string>,
    context: { signal: AbortSignal },
  ) => void | Promise<void>;
  onComplete?: (values: Record<string, string>) => void;
  nextLabel?: string;
  backLabel?: string;
  submitLabel?: string;
  loadingLabel?: string;
  successTitle?: string;
  successMessage?: ReactNode;
}
export function MultiStepForm({
  steps,
  value,
  defaultValue = {},
  onValueChange,
  step,
  defaultStep = 0,
  onStepChange,
  onSubmit,
  onComplete,
  nextLabel = "Next",
  backLabel = "Back",
  submitLabel = "Send message",
  loadingLabel = "Sending",
  successTitle = "Message sent",
  successMessage = "Thanks for reaching out. We will be in touch.",
  ...appearance
}: MultiStepFormProps) {
  const [values, setValues] = useControlValue(value, defaultValue, onValueChange);
  const [current, setCurrent] = useControlValue(step, defaultStep, onStepChange);
  const index = Math.min(Math.max(0, current), Math.max(0, steps.length - 1));
  const [direction, setDirection] = useState(1);
  const [status, setStatus] = useState<"idle" | "submitting" | "complete">("idle");
  const [error, setError] = useState("");
  const form = useRef<HTMLFormElement>(null);
  const abort = useRef<AbortController | null>(null);
  const moved = useRef(false);
  const transition = useControlTransition(appearance.duration);
  const id = useId();
  const active = steps[index];
  const [renderedStep, setRenderedStep] = useState<string | undefined>(active?.id);
  const trackStep = useCallback((node: HTMLDivElement | null) => {
    if (node) setRenderedStep(node.dataset.formStep);
  }, []);
  const transitioning = renderedStep !== active?.id;
  useEffect(() => () => abort.current?.abort(), []);
  const setValue = (name: string, next: string) => setValues({ ...values, [name]: next });
  function move(next: number) {
    if (transitioning) return;
    moved.current = true;
    setDirection(next > index ? 1 : -1);
    setError("");
    setCurrent(next);
  }
  async function submit() {
    if (!active || transitioning || status === "submitting") return;
    if (!form.current?.reportValidity()) return;
    const invalid = active.validate?.(values);
    if (invalid) {
      setError(invalid);
      return;
    }
    if (index < steps.length - 1) {
      move(index + 1);
      return;
    }
    const controller = new AbortController();
    abort.current = controller;
    setStatus("submitting");
    setError("");
    try {
      await onSubmit?.({ ...values }, { signal: controller.signal });
      if (controller.signal.aborted) return;
      setStatus("complete");
      onComplete?.({ ...values });
    } catch (e) {
      if (controller.signal.aborted) return;
      setStatus("idle");
      setError(e instanceof Error ? e.message : "Could not send. Please try again.");
    }
  }
  return (
    <>
      <ControlStyles />
      <form
        ref={form}
        className={`z-mc z-mc-form ${appearance.className ?? ""}`}
        style={controlVariables(appearance)}
        onSubmit={(event) => {
          event.preventDefault();
          void submit();
        }}
        aria-busy={status === "submitting"}
      >
        {status === "complete" ? (
          <motion.div
            className="z-mc-form-success"
            role="status"
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={transition}
          >
            <span className="z-mc-form-success-mark" aria-hidden="true">
              ✓
            </span>
            <h2>{successTitle}</h2>
            <p>{successMessage}</p>
          </motion.div>
        ) : (
          active && (
            <>
              <div
                className="z-mc-form-progress"
                aria-label={`Step ${index + 1} of ${steps.length}`}
              >
                <ControlRoll id={index} duration={appearance.duration}>
                  {String(index + 1).padStart(2, "0")}
                </ControlRoll>
                <span className="z-mc-muted"> / {String(steps.length).padStart(2, "0")}</span>
                <div className="z-mc-form-track">
                  <motion.span
                    initial={false}
                    animate={{ scaleX: (index + 1) / steps.length }}
                    transition={transition}
                  />
                </div>
              </div>
              <div className="z-mc-form-window">
                <AnimatePresence mode="wait" initial={false} custom={direction}>
                  <motion.div
                    ref={trackStep}
                    data-form-step={active.id}
                    className="z-mc-form-step"
                    key={active.id}
                    custom={direction}
                    variants={{
                      enter: (d: number) => ({ x: d * 45, opacity: 0 }),
                      active: { x: 0, opacity: 1 },
                      exit: (d: number) => ({ x: -d * 45, opacity: 0 }),
                    }}
                    initial="enter"
                    animate="active"
                    exit="exit"
                    transition={transition}
                    onAnimationComplete={(definition) => {
                      if (definition === "active" && moved.current) {
                        form.current?.querySelector<HTMLElement>("input,textarea,select")?.focus();
                        moved.current = false;
                      }
                    }}
                  >
                    <h2>{active.title}</h2>
                    <div className="z-mc-form-fields">
                      {active.render?.({ values, setValue, submitting: status === "submitting" })}
                      {active.fields?.map((field) => {
                        const props = {
                          "aria-label": field.label + (field.required ? " *" : ""),
                          id: `${id}-${field.name}`,
                          name: field.name,
                          value: values[field.name] ?? "",
                          required: field.required,
                          disabled: status === "submitting",
                          onChange: (e: { target: { value: string } }) =>
                            setValue(field.name, e.target.value),
                        };
                        return (
                          <label key={field.name} className="z-mc-form-field" htmlFor={props.id}>
                            {field.type === "textarea" ? (
                              <textarea {...props} placeholder=" " minLength={field.minLength} />
                            ) : field.type === "select" ? (
                              <select {...props}>
                                <option value="" disabled>
                                  Select {field.label.toLowerCase()}
                                </option>
                                {field.options?.map((option) => (
                                  <option value={option.value} key={option.value}>
                                    {option.label}
                                  </option>
                                ))}
                              </select>
                            ) : (
                              <input
                                {...props}
                                type={field.type ?? "text"}
                                placeholder=" "
                                minLength={field.minLength}
                                autoComplete={field.autoComplete}
                              />
                            )}
                            <span>
                              {field.label}
                              {field.required ? " *" : ""}
                            </span>
                          </label>
                        );
                      })}
                    </div>
                  </motion.div>
                </AnimatePresence>
              </div>
              {error && (
                <p className="z-mc-form-error" role="alert">
                  {error}
                </p>
              )}
              <div className="z-mc-form-actions">
                {index > 0 && (
                  <button
                    type="button"
                    className="z-mc-form-back"
                    disabled={status === "submitting" || transitioning}
                    onClick={() => move(index - 1)}
                  >
                    {backLabel}
                  </button>
                )}
                <button
                  type="submit"
                  className="z-mc-pill"
                  disabled={status === "submitting" || transitioning}
                >
                  <ControlRoll id={status + index} duration={appearance.duration}>
                    {status === "submitting"
                      ? loadingLabel
                      : index === steps.length - 1
                        ? submitLabel
                        : nextLabel}
                  </ControlRoll>
                </button>
              </div>
            </>
          )
        )}
      </form>
    </>
  );
}
